fn pad2(n){
    if n < 10 { return "0" + n }
    return "" + n
}
// local clock as "HH:MM" (+8 like the greeting: card-host reports UTC)
fn now_hhmm(){
    let t = mod.std.local_time()
    let h = t.hour + 8
    if h >= 24 { h = h - 24 }
    return pad2(h) + ":" + pad2(t.minute)
}

