// ---- navigation & actions ---------------------------------------------------
// floating-pill guard: a tap reaches EVERY overlapping GestureView, so a
// nav tap also fires the handler of whatever card/button sits under the
// pill. go() stamps the drift clock; content handlers entered within 0.25s
// (same dispatch) are dropped. Either dispatch order converges on the nav
// switch: card-first leaves the flag unset and go() clears open_idx after.
fn nav_recent(){
    let d = anim_t - nav_gate_t
    if d < 0 { return false }
    return d < 0.25
}
fn go(s){
    nav_gate_t = anim_t
    screen = s
    open_idx = -1
    send_state = "idle"
    send_error_msg = ""
    // 0.8.0: nav entry to 写信 always means FRESH compose. A nav tap passes
    // through to whatever lies under the pill (0.7.5 finding) — if that was
    // a detail screen's 回复, open_compose fires in the same dispatch and its
    // reply_idx survives go(), silently binding the next write to the wrong
    // thread (route forensics: 写信 showing 外婆's subject). Resetting here
    // converges both dispatch orders: 回复-first is wiped, go-first gates it.
    if s == "write" {
        reply_idx = -1
        to_input = mails[0].handle
        subject_input = "Re: 周末去海边吗?"
        live_preview = ""
        tone = 2
        tone_src = "canned"
        tone_note = ""
        open_compose_reset_draft()
    }
    repaint()
}
