// schedule proposal (.ics): the export file is written to the app sandbox
// first, then handed to the host's export sheet; DTSTART shifts with the
// in-card ±1h correction
fn ev_stamp(m){
    let e = m.ev
    let h = e.h + m.ev_shift
    if h < 0 { h = 0 }
    if h > 23 { h = 23 }
    return "" + e.y + pad2(e.mo) + pad2(e.d) + "T" + pad2(h) + pad2(e.mi) + "00"
}
fn ev_time_shown(m){
    let h = m.ev.h + m.ev_shift
    if h < 0 { h = 0 }
    if h > 23 { h = 23 }
    return pad2(h) + ":" + pad2(m.ev.mi)
}
