// 0.8.0 batch sweep bar: floats above the nav pill while a vibe filter is
// active. Taps stamp the nav gate so a mail card scrolling under the bar is
// not opened by the same dispatch (the floating-pill guard's rule).
fn sweep_bar(){
    RoundedView{width: Fill height: Fit padding: Inset{top: 10 bottom: 10 left: 14 right: 14}
        draw_bg +: {color: paper3 border_radius: 18.0 border_size: 1.0 border_color: line2}
        if sweep == "confirm" {
            View{width: Fill height: Fit flow: Down spacing: 8
                Label{width: Fill text: "将归档 " + vibe_count(filter) + " 封「" + vibe_label(filter) + "」邮件,可随时在「我的 → 归档恢复」找回" draw_text.color: ink draw_text.text_style.font_size: 11}
                View{width: Fill height: Fit flow: Right spacing: 9
                    GestureView{width: Fill height: 32 on_tap: |x, y| sweep_do()
                        RoundedView{width: Fill height: 32 draw_bg +: {color: ink border_radius: 16.0} align: Align{x: 0.5 y: 0.5}
                            Label{text: "确认归档" draw_text.color: paper draw_text.text_style: theme.font_bold{font_size: 11}}
                        }
                    }
                    GestureView{width: Fill height: 32 on_tap: |x, y| sweep_cancel()
                        RoundedView{width: Fill height: 32 draw_bg +: {color: paper2 border_radius: 16.0 border_size: 1.0 border_color: line2} align: Align{x: 0.5 y: 0.5}
                            Label{text: "取消" draw_text.color: inkSoft draw_text.text_style.font_size: 11}
                        }
                    }
                }
            }
        } else {
            if sweep == "done" {
                View{width: Fill height: Fit flow: Right spacing: 10 align: Align{y: 0.5}
                    Label{width: Fill text: "已归档 " + sweep_n + " 封" draw_text.color: chipFgCalm draw_text.text_style.font_size: 11}
                    GestureView{width: Fit height: 32 on_tap: |x, y| sweep_undo()
                        RoundedView{width: Fit height: 32 padding: Inset{left: 14 right: 14} draw_bg +: {color: paper2 border_radius: 16.0 border_size: 1.0 border_color: line2} align: Align{x: 0.5 y: 0.5}
                            Label{text: "撤销" draw_text.color: ink draw_text.text_style.font_size: 11}
                        }
                    }
                }
            } else {
                View{width: Fill height: Fit flow: Right spacing: 10 align: Align{y: 0.5}
                    Label{width: Fill text: "把 " + vibe_count(filter) + " 封「" + vibe_label(filter) + "」邮件归档" draw_text.color: ink draw_text.text_style.font_size: 11}
                    GestureView{width: Fit height: 32 on_tap: |x, y| sweep_ask()
                        RoundedView{width: Fit height: 32 padding: Inset{left: 14 right: 14} draw_bg +: {color: ink border_radius: 16.0} align: Align{x: 0.5 y: 0.5}
                            Label{text: "归档全部" draw_text.color: paper draw_text.text_style.font_size: 11}
                        }
                    }
                }
            }
        }
    }
}
fn inbox_screen(){
    ScrollYView{width: Fill height: Fill flow: Down
        View{width: Fill height: Fit flow: Down spacing: 12 padding: Inset{top: 14 bottom: 92 left: 16 right: 16}
            // greeting + brand aura (the aura sways on the drift clock)
            View{width: Fill height: Fit flow: Right align: Align{y: 0.0}
                View{width: Fill height: Fit flow: Down
                    Label{text: greeting_word + "," draw_text.color: ink draw_text.text_style: theme.font_bold{font_size: 22}}
                    Label{text: "你有 " + unread_cnt() + " 封未读邮件" draw_text.color: ink draw_text.text_style: theme.font_bold{font_size: 22}}
                }
                View{width: 76 height: 84 align: Align{x: 1.0 y: 0.5}
                    View{width: 64 height: 64 align: Align{x: 0.5 y: 0.5}
                        aura_brand(64)}}
            }
            // AI digest line
            RoundedView{width: Fill height: Fit padding: Inset{top: 10 bottom: 10 left: 12 right: 12}
                draw_bg +: {color: paper3 border_radius: 16.0 border_size: 1.0 border_color: line} flow: Down spacing: 4
                View{width: Fill height: Fit flow: Right spacing: 6 align: Align{y: 0.5}
                    View{width: 12 height: 12 align: Align{x: 0.5 y: 0.5}
                        spark_icon(inkSoft, 11)}
                    View{width: Fill height: Fit flow: Right spacing: 6 align: Align{y: 0.5}
                        Label{width: Fill text: digest_shown() draw_text.color: inkSoft draw_text.text_style.font_size: 11}
                        Label{text: digest_src_word() draw_text.color: inkDim draw_text.text_style.font_size: 9}
                    }
                }
                Label{width: Fill text: banner_line() draw_text.color: inkDim draw_text.text_style.font_size: 9}
                if mail_link == "live" {
                    if mail_src == "practice" {
                        Label{width: Fill text: "真实邮件正在同步,稍候片刻…" draw_text.color: inkDim draw_text.text_style.font_size: 9}
                    }
                }
                if filter != "all" {
                    Label{width: Fill text: filter_note() draw_text.color: inkSoft draw_text.text_style.font_size: 9.5}
                }
            }
            // vibe filter chips — six fit the content width, no scrolling
            View{width: Fill height: Fit flow: Right spacing: 4 padding: Inset{top: 2 bottom: 2}
                filter_chip("all", "全部")
                filter_chip("focus", "专注")
                filter_chip("joy", "愉悦")
                filter_chip("calm", "平静")
                filter_chip("spark", "灵感")
                filter_chip("link", "连接")
            }
            // the list itself
            View{width: Fill height: Fit flow: Down spacing: 10
                for i in mails.len() {
                    if mails[i].boxed == "" {
                        if filter == "all" {
                            mail_card(i)
                        } else {
                            if mails[i].vibe == filter { mail_card(i) }
                        }
                    }
                }
                if visible_count() == 0 { inbox_empty() }
            }
        }
    }
}

