        View{width: Fill height: Fit flow: Right spacing: 8 padding: Inset{top: 2 bottom: 2}
            Label{width: 40 text: "事项" draw_text.color: inkDim draw_text.text_style.font_size: 11}
            Label{width: Fill text: m.ev.title draw_text.color: ink draw_text.text_style.font_size: 12}
