        GestureView{width: Fill height: Fit on_tap: |x, y| shift_ev(i)
            View{width: Fill height: Fit flow: Right spacing: 8 padding: Inset{top: 2 bottom: 2}
                Label{width: 40 text: "时间" draw_text.color: inkDim draw_text.text_style.font_size: 11}
