// ---- orbit (star map) -------------------------------------------------------
// 0.7.5: the field is FILL-WIDTH (fixed height 560) and every anchor is a
// FRACTION of it, so the constellation spreads across whatever width the
// window gives — the old fixed 380 canvas left a narrow centred strip with
// dead flanks on wide screens. Size = 52 + imp*0.62; drift is fractional
// too (the px swing of the phone design, expressed against any width).
fn orbit_fx(i){
    if i == 0 { return 0.13 }
    if i == 1 { return 0.65 }
    if i == 2 { return 0.29 }
    if i == 3 { return 0.76 }
    if i == 4 { return 0.10 }
    if i == 5 { return 0.62 }
    if i == 6 { return 0.36 }
    return 0.80
}
fn orbit_fy(i){
    if i == 0 { return 0.12 }
    if i == 1 { return 0.06 }
    if i == 2 { return 0.38 }
    if i == 3 { return 0.36 }
    if i == 4 { return 0.64 }
    if i == 5 { return 0.62 }
    if i == 6 { return 0.84 }
    return 0.82
}
fn bubble(i){
    let m = mails[i]
    let size = 52 + m.imp * 62 / 100
    let fx = orbit_fx(i) + cos(anim_t * (0.6 + i * 0.07)) * 0.012
    let fy = orbit_fy(i) + sin(anim_t * (0.8 + i * 0.09)) * 0.012
    let c = vibe_color(m.vibe)
    // the wrapper canvas is 1.66x the bubble (leftover glow headroom, the
    // halos themselves were removed in 0.7.2 — the link blue's halo read as
    // stray circles while the other vibes' were invisible)
    let g = size * 1.66
    View{width: Fill height: 560 align: Align{x: fx y: fy}
        View{width: g height: g flow: Overlay
            GestureView{width: size height: size align: Align{x: 0.5 y: 0.5} on_tap: |x, y| open_mail(i)
                RoundedView{width: size height: size draw_bg +: {color: c border_radius: size / 2.0} flow: Overlay align: Align{x: 0.5 y: 0.5}
                    // radial-gradient feel: broad soft lift + tight core at 34% 30%
                    View{width: size height: size align: Align{x: 0.34 y: 0.30}
                        View{width: size * 0.64 height: size * 0.64 align: Align{x: 0.5 y: 0.5}
                            RoundedView{width: size * 0.64 height: size * 0.64 draw_bg +: {color: #xffffff1c border_radius: size * 0.32}}}}
                    View{width: size height: size align: Align{x: 0.34 y: 0.30}
                        View{width: size * 0.28 height: size * 0.28 align: Align{x: 0.5 y: 0.5}
                            RoundedView{width: size * 0.28 height: size * 0.28 draw_bg +: {color: #xffffff59 border_radius: size * 0.14}}}}
                    View{width: size height: size flow: Down spacing: 2 align: Align{x: 0.5 y: 0.5}
                        Label{text: m.bname draw_text.color: onC draw_text.text_style: theme.font_bold{font_size: 9} align: Align{x: 0.5}}
                        if m.unread {
                            View{width: 4 height: 4 align: Align{x: 0.5}
                                RoundedView{width: 4 height: 4 draw_bg +: {color: onC border_radius: 2.0}}}
                        }
                    }
                }
            }
        }
    }
}
// 0.8.0 时间轴 (rebuilt): a real timeline, not shrunk bubbles — a left spine
// with one vibe-coloured node per mail, time on the left gutter, and a
// compact card on the right. Newest on top; every row opens the mail. The
// spine segments are per-row 2px rects, so the line reads continuous at any
// row height (no drawing primitives beyond rounded rects exist).
fn timeline_node(i){
    let m = mails[i]
    View{width: 18 height: Fill flow: Overlay
        // spine segment (continuous across rows)
        View{width: 18 height: Fill align: Align{x: 0.5}
            RoundedView{width: 2 height: Fill draw_bg +: {color: line border_radius: 1.0}}}
        // the node: vibe dot, ringed + halo when unread
        View{width: 18 height: Fill align: Align{x: 0.5 y: 0.5}
            View{width: 18 height: 18 align: Align{x: 0.5 y: 0.5}
                RoundedView{width: pick(m.unread, 16, 10) height: pick(m.unread, 16, 10)
                    draw_bg +: {color: pick(m.unread, chip_bg(m.vibe), vibe_color(m.vibe))
                               border_radius: pick(m.unread, 8.0, 5.0)
                               border_size: pick(m.unread, 2.0, 0.0)
                               border_color: vibe_color(m.vibe)}}}
        }
    }
}
