// vibe distribution bar row for the weekly report
fn weekly_bar(v){
    let n = vibe_count(v)
    // bar length is normalised by the top vibe: an uncapped n*26 overflows
    // the card when one vibe dominates a busy week
    let maxc = vibe_count(top_vibe())
    let unit = 26
    if maxc > 8 { unit = 208 / maxc }
    View{width: Fill height: Fit flow: Right spacing: 8 align: Align{y: 0.5} padding: Inset{top: 3 bottom: 3}
        Label{width: 34 text: vibe_label(v) draw_text.color: inkSoft draw_text.text_style.font_size: 10.5}
        RoundedView{width: 8 + n * unit height: 10 draw_bg +: {color: vibe_color(v) border_radius: 5.0}}
        Label{text: "" + n draw_text.color: ink draw_text.text_style.font_size: 10.5}
    }
}
