// ---- write (tone slider) ------------------------------------------------------
// the drawn slider: visuals first, three tap segments minted LAST so they
// sit above the track for hit testing (late children win in an Overlay).
// 0.7.5: track/dots/knob/tap stack is ONE fixed-348 overlay centred by a
// Fill wrapper — in a wider column the Fill-wide dot/knob rows would drift
// off the 348 track; fixed siblings cannot.
fn tone_col(k){
    // one adaptive stop: dot centred, knob (with paper ring) stacked over it
    // when active, whole column tappable — alignment is structural
    GestureView{width: Fill height: 28 on_tap: |x, y| set_tone(k)
        View{width: Fill height: 28 flow: Overlay
            View{width: Fill height: 28 align: Align{x: 0.5 y: 0.5}
                RoundedView{width: 8 height: 8 draw_bg +: {color: pick(tone == k, pinkC, line2) border_radius: 4.0}}}
            if tone == k {
                View{width: Fill height: 28 align: Align{x: 0.5 y: 0.5}
                    RoundedView{width: 20 height: 20 draw_bg +: {color: ink border_radius: 10.0 border_size: 3.0 border_color: paper3}}}
            }
        }
    }
}
fn tone_label_col(k, label){
    // 24 (was 20): the fontless release build's fallback CJK metrics make a
    // 9.5px line box taller than 20 and the glyphs clip at the container edge
    GestureView{width: Fill height: 24 on_tap: |x, y| set_tone(k)
        View{width: Fill height: 24 align: Align{x: 0.5 y: 0.5}
            Label{text: label draw_text.color: pick(tone == k, ink, inkSoft)
                   draw_text.text_style.font_size: 9.5}}
    }
}
// ---- write (tone slider) ------------------------------------------------------
// 0.7.5 REDESIGN — three EQUAL FILL columns over a full-width track: dot,
// knob and tap zone share one column each, so every stop is aligned by
// construction at ANY width (the old fixed-348 stack put the knob off-stop
// for 真诚/正式 since 0.7.0 — only the middle stop could ever line up).
fn tone_slider(){
    View{width: Fill height: Fit flow: Down spacing: 7
        View{width: Fill height: 28 flow: Overlay
            // base track
            View{width: Fill height: 28 align: Align{y: 0.5}
                RoundedView{width: Fill height: 6 draw_bg +: {color: paper2 border_radius: 3.0 border_size: 1.0 border_color: line}}}
            // five equal stops: dot + knob + tap zone per column
            View{width: Fill height: 28 flow: Right
                tone_col(0)
                tone_col(1)
                tone_col(2)
                tone_col(3)
                tone_col(4)
            }
        }
        // labels (tappable too — same five columns)
        View{width: Fill height: Fit flow: Right
            tone_label_col(0, "真诚")
            tone_label_col(1, "幽默")
            tone_label_col(2, "友好")
