                    View{width: Fill height: Fit flow: Down spacing: 2
                        if mail_link == "live" {
                            Label{text: account_addr draw_text.color: ink draw_text.text_style.font_size: 11.5}
                            Label{text: "已通过 OctoSense 邮件服务登录" draw_text.color: inkSoft draw_text.text_style.font_size: 9.5}
                        } else {
                            Label{text: "me@octomail.io" draw_text.color: ink draw_text.text_style.font_size: 11.5}
                            Label{text: "演示模式 · 未连接邮件服务" draw_text.color: inkSoft draw_text.text_style.font_size: 9.5}
                        }
                    }
                }
                Label{width: Fill text: "VibeMail 0.8.0 · vibemail · 有情绪的邮件 · 带只读助手" draw_text.color: inkDim draw_text.text_style.font_size: 9}
            }
        }
    }
}

// ---- bottom nav -----------------------------------------------------------
fn nav_item(label, target){
    let act = screen == target && open_idx < 0
    GestureView{width: Fit height: Fit on_tap: |x, y| go(target)
        RoundedView{width: Fit height: Fit padding: Inset{top: 6 bottom: 6 left: 16 right: 16}
            draw_bg +: {color: pick(act, ink, #x00000000) border_radius: 19.0}
            View{width: Fit height: Fit flow: Down spacing: 2 align: Align{x: 0.5}
                View{width: 16 height: 16 align: Align{x: 0.5 y: 0.5}
                    if target == "inbox" { tray_icon(pick(act, paper, inkSoft), 16) } else {
                    if target == "orbit" { orbit_icon(pick(act, paper, inkSoft), 16) } else {
                    if target == "write" { pen_icon(pick(act, paper, inkSoft), 16, pick(act, ink, paper)) } else {
                    sliders_icon(pick(act, paper, inkSoft), 16) }}}}
                Label{text: label draw_text.color: pick(act, paper, inkSoft) draw_text.text_style.font_size: 9}
            }
        }
    }
}
fn bottom_nav(){
    // glass pill FLOATING over the column's bottom edge — the screen scrolls
    // behind it, so every screen keeps a bottom inset (88) with no tappable
    // card under the band: taps reach EVERY overlapping GestureView here, and
    // a card under the pill would open together with the nav item
    View{width: Fill height: Fit align: Align{x: 0.5} padding: Inset{top: 8 bottom: 16}
        RoundedView{width: Fit height: Fit padding: Inset{top: 5 bottom: 5 left: 7 right: 7}
            draw_bg +: {color: glass border_radius: 27.0 border_size: 1.0 border_color: line}
            View{width: Fit height: Fit flow: Right spacing: 2 align: Align{y: 0.5}
                nav_item("收件箱", "inbox")
                nav_item("星轨", "orbit")
                nav_item("写信", "write")
                nav_item("我的", "set")
            }
        }
    }
}

// ---- root -----------------------------------------------------------------
// ONE on_render root mints the whole window (probed: separate on_render
// underlays composite above later UI, so layers must share a single mint
// with the ground first and the nav last): full-window paper ground, then
// the app column. The static SolidView ground only shows if the app fails
// to boot.
// WIDTH ADAPTATION (0.7.5): the column FILLS the window — fluid at every
// width. A fixed 660 with centring was probed first and does NOT clamp to
// the container: in a 412 window it centre-overflows and clips both edges
// (unread dots left, 连接 chip right), so the 0.6.x "fixed width clamps"
// note is dead. No window-size API exists for scripts either (only math/
// json/text/array/object + host services) — Fill is the only honest
// responsive primitive. Inner fixed-width pieces (tone slider, star map)
// are centred by their Fill wrappers so they keep proportions when wide.
SolidView{width: Fill height: Fill flow: Overlay draw_bg.color: #xeaeae3
    appc := View{width: Fill height: Fill flow: Overlay on_render: || {
        // full-window theme ground
        RoundedView{width: Fill height: Fill draw_bg +: {color: paper border_radius: 0.0}}
        // app column — fluid Fill. The SCREEN fills the whole column and the
        // glass nav pill FLOATS over its bottom edge (0.7.5 user call: the
        // pill stays, but the paper slab around it goes — the pill hangs on
        // the window like the reference). Overlay caveat: a tap reaches EVERY
        // overlapping GestureView, so the list keeps a bottom inset (the nav
        // band) with no tappable card content under the pill; the pill's own
        // items sit inside their glass capsule, not over any card.
        View{width: Fill height: Fill flow: Overlay
            View{width: Fill height: Fill flow: Down
                // active screen (scrolls itself, full column height)
                View{width: Fill height: Fill flow: Overlay
                    if open_idx >= 0 {
                        detail_screen()
                    } else {
                        if screen == "inbox" { inbox_screen() }
                        if screen == "orbit" { orbit_screen() }
                        if screen == "write" { write_screen() }
                        if screen == "set" { set_screen() }
                    }
                }
            }
            // 0.8.0: batch sweep bar floats above the nav pill while a vibe
            // filter is active (hidden again once the sweep settles)
            if screen == "inbox" {
                if open_idx < 0 {
                    if filter != "all" {
                        if sweep != "" || vibe_count(filter) > 0 {
                            View{width: Fill height: Fill align: Align{x: 0.5 y: 1.0} padding: Inset{bottom: 84 left: 16 right: 16}
                                sweep_bar()
                            }
                        }
                    }
                }
            }
            // glass pill floats over the column's bottom edge — the anchor
            // wrapper is Fill-height so its y:1.0 lands the Fit pill at the
            // bottom (a Fit wrapper in Overlay parks at the top, 0.7.5 probe)
            View{width: Fill height: Fill align: Align{x: 0.5 y: 1.0} padding: Inset{bottom: 14}
                bottom_nav()
            }
        }
    }}
}
